-- create database tutor_matching_db;
-- use tutor_matching_db;
-- TutorMatch DDL Script -- Milestone 4: Database Setup -- Engine: MySQL / InnoDB  CREATE DATABASE IF NOT EXISTS tutormatch; USE tutormatch;
-- 1. Categories CREATE TABLE Categories (     category_id   INT AUTO_INCREMENT PRIMARY KEY,     category_name VARCHAR(100) NOT NULL UNIQUE,     description   TEXT );
-- 2. Students CREATE TABLE Students (     student_id  INT AUTO_INCREMENT PRIMARY KEY,     full_name   VARCHAR(150) NOT NULL,     grade_level VARCHAR(50)  NOT NULL,     area        VARCHAR(100) NOT NULL,     phone       VARCHAR(20)  NOT NULL,     email       VARCHAR(150) NOT NULL UNIQUE,     created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,     INDEX idx_students_area (area) );
-- 3. Tutors CREATE TABLE Tutors (     tutor_id      INT AUTO_INCREMENT PRIMARY KEY,     full_name     VARCHAR(150)   NOT NULL,     qualification VARCHAR(200)   NOT NULL,     area          VARCHAR(100)   NOT NULL,     phone         VARCHAR(20)    NOT NULL,     email         VARCHAR(150)   NOT NULL UNIQUE,     hourly_rate   DECIMAL(10, 2) NOT NULL CHECK (hourly_rate > 0),     is_available  TINYINT(1)     NOT NULL DEFAULT 1                       CHECK (is_available IN (0, 1)),     created_at    DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,     INDEX idx_tutors_area (area),     INDEX idx_tutors_available (is_available) );
-- 4. Subjects CREATE TABLE Subjects (     subject_id   INT AUTO_INCREMENT PRIMARY KEY,     subject_name VARCHAR(150) NOT NULL UNIQUE,     category_id  INT          NOT NULL,     FOREIGN KEY (category_id) REFERENCES Categories(category_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_subjects_category (category_id) );
-- 5. Tutor_Subjects CREATE TABLE Tutor_Subjects (     tutor_subject_id INT AUTO_INCREMENT PRIMARY KEY,     tutor_id         INT NOT NULL,     subject_id       INT NOT NULL,     UNIQUE KEY uq_tutor_subject (tutor_id, subject_id),     FOREIGN KEY (tutor_id)   REFERENCES Tutors(tutor_id)         ON UPDATE CASCADE ON DELETE CASCADE,     FOREIGN KEY (subject_id) REFERENCES Subjects(subject_id)         ON UPDATE CASCADE ON DELETE CASCADE,     INDEX idx_ts_tutor   (tutor_id),     INDEX idx_ts_subject (subject_id) );
-- 6. Matches CREATE TABLE Matches (     match_id   INT AUTO_INCREMENT PRIMARY KEY,     student_id INT         NOT NULL,     tutor_id   INT         NOT NULL,     match_date DATE        NOT NULL,     status     VARCHAR(10) NOT NULL DEFAULT 'Active'                    CHECK (status IN ('Active', 'Closed')),     FOREIGN KEY (student_id) REFERENCES Students(student_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     FOREIGN KEY (tutor_id)   REFERENCES Tutors(tutor_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_matches_student (student_id),     INDEX idx_matches_tutor   (tutor_id),     INDEX idx_matches_status  (status) );
-- 7. Bookings CREATE TABLE Bookings (     booking_id     INT AUTO_INCREMENT PRIMARY KEY,     student_id     INT         NOT NULL,     tutor_id       INT         NOT NULL,     subject_id     INT         NOT NULL,     booking_date   DATE        NOT NULL,     preferred_time TIME        NOT NULL,     message        TEXT,     status         VARCHAR(15) NOT NULL DEFAULT 'Pending'                        CHECK (status IN ('Pending', 'Confirmed', 'Cancelled')),     created_at     DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP,     FOREIGN KEY (student_id) REFERENCES Students(student_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     FOREIGN KEY (tutor_id)   REFERENCES Tutors(tutor_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     FOREIGN KEY (subject_id) REFERENCES Subjects(subject_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_bookings_student (student_id),     INDEX idx_bookings_tutor   (tutor_id),     INDEX idx_bookings_subject (subject_id),     INDEX idx_bookings_status  (status) );
-- 8. Sessions CREATE TABLE Sessions (     session_id    INT AUTO_INCREMENT PRIMARY KEY,     match_id      INT         NOT NULL,     session_date  DATE        NOT NULL,     start_time    TIME        NOT NULL,     duration_mins INT         NOT NULL CHECK (duration_mins > 0),     attendance    VARCHAR(15) NOT NULL                       CHECK (attendance IN ('Present', 'Absent', 'Cancelled')),     FOREIGN KEY (match_id) REFERENCES Matches(match_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_sessions_match (match_id),     INDEX idx_sessions_date  (session_date) );
-- 9. Payments CREATE TABLE Payments (     payment_id   INT AUTO_INCREMENT PRIMARY KEY,     session_id   INT            NOT NULL UNIQUE,     amount       DECIMAL(10, 2) NOT NULL CHECK (amount >= 0),     payment_date DATE           NOT NULL,     status       VARCHAR(10)    NOT NULL DEFAULT 'Pending'                      CHECK (status IN ('Paid', 'Pending', 'Due')),     FOREIGN KEY (session_id) REFERENCES Sessions(session_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_payments_status (status) );
-- 10. Reviews CREATE TABLE Reviews (     review_id   INT AUTO_INCREMENT PRIMARY KEY,     student_id  INT         NOT NULL,     tutor_id    INT         NOT NULL,     rating      TINYINT     NOT NULL CHECK (rating BETWEEN 1 AND 5),     review_text TEXT,     review_date DATE        NOT NULL,     UNIQUE KEY uq_student_tutor_review (student_id, tutor_id),     FOREIGN KEY (student_id) REFERENCES Students(student_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     FOREIGN KEY (tutor_id)   REFERENCES Tutors(tutor_id)         ON UPDATE CASCADE ON DELETE RESTRICT,     INDEX idx_reviews_student (student_id),     INDEX idx_reviews_tutor   (tutor_id) );
